import{_ as o,l,o as t,c as h,v as i,p as n,x as r,d as s,i as m,S as f}from"./chunks/framework.InCnrqk-.js";const x=JSON.parse('{"title":"傅里叶变换对与卷积","description":"","frontmatter":{"title":"傅里叶变换对与卷积","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/fourier-pairs-convolution.md","filePath":"litho/fourier-pairs-convolution.md","lastUpdated":1789023840000}'),d={name:"litho/fourier-pairs-convolution.md"};function p(c,a,u,b,T,_){const e=l("Mermaid");return t(),h("div",null,[a[1]||(a[1]=i('<h1 id="傅里叶变换对与卷积" tabindex="-1">傅里叶变换对与卷积 <a class="header-anchor" href="#傅里叶变换对与卷积" aria-label="Permalink to &quot;傅里叶变换对与卷积&quot;">​</a></h1><div class="epigraph"><p>成像计算不是另起一套光学；它把空域的卷积写成频域的相乘，把光瞳写成几对已知的傅里叶对。</p><footer>—— Goodman, Introduction to Fourier Optics 对卷积定理与基本变换对的表述</footer></div><p><a href="/litho/patterning-inspection-tools">上一课</a>把主干收到检测与量测设备。主干里已经有<a href="/litho/abbe-imaging">阿贝成像</a>、<a href="/litho/hopkins-tcc">Hopkins TCC</a>、<a href="/litho/rayleigh-litho">瑞利判据</a>和 <a href="/litho/mtf-optics">MTF</a>。缺口是：<strong>还没有把「频谱 × 光瞳」收成后课可以反复调用的代数骨架</strong>——傅里叶变换对与卷积。本课不重推 \\(\\mathrm{CD}=k_1\\lambda/\\mathrm{NA}\\)；那条产线式子默认本课的对已经会用。后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>阿贝课把像场写成物频谱乘光瞳再逆变换；Hopkins 课把强度写成双线性核。两边都在暗用同一件事：空域卷积 \\(\\leftrightarrow\\) 频域相乘。若每次成像都从<a href="/litho/em-wave-index">单色波与光程</a>重推亥姆霍兹，后课的采样、PSF、SOCS 会失去公共符号。</p><p>缺口因此是钉死三件事：傅里叶变换对是哪些、卷积定理说什么、光刻里「物体 / 核 / 像」分别对应哪一侧。不要从显微镜两针孔或产线 \\(k_1\\) 起笔。</p><h3 id="先约定符号" tabindex="-1">先约定符号 <a class="header-anchor" href="#先约定符号" aria-label="Permalink to &quot;先约定符号&quot;">​</a></h3><p>平面上</p> \\[T(\\mathbf{f})=\\iint t(\\mathbf{x})\\,e^{-2\\pi i\\mathbf{f}\\cdot\\mathbf{x}}\\,d^2\\mathbf{x},\\qquad t=\\mathcal{F}^{-1}\\{T\\}. \\]<p>\\(t\\) 是物面透过率（或等效薄物体），\\(T\\) 是物频谱，\\(\\mathbf{f}\\) 的单位是长度\\(^{-1}\\)。光瞳坐标与像方空间频率对齐的约定，沿用阿贝课，本课不再改轴。</p><p><span class="marginnote">一维示意用 \\(x\\leftrightarrow f\\) 即可；晶圆图形是二维的，后课孔与拐角必须回到 \\(\\mathbf{x},\\mathbf{f}\\)。不要把「线栅的一维傅里叶变换」当成全部成像。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>卷积定理：\\((t*h)(\\mathbf{x})=\\mathcal{F}^{-1}\\{T(\\mathbf{f})H(\\mathbf{f})\\}\\)。相干成像里 \\(h\\) 是振幅点扩散，\\(H\\) 就是光瞳 \\(P\\)；非相干成像里卷积写在强度上，\\(H\\) 换成 OTF。部分相干没有单条 \\(H\\)，但每一源点的相干通道仍是本课这一对。</p><p>后课反复出现的对，本课一次性列出，后面只引用：</p><ul><li>\\(\\mathrm{rect}(x)\\leftrightarrow\\mathrm{sinc}(f)\\)：有限缝、扫描狭缝、矩形开口的一维骨架。</li><li>\\(\\mathrm{circ}(r)\\leftrightarrow\\mathrm{jinc}\\)（第一类贝塞尔）：圆孔光瞳 ↔ 艾里核，下一课 PSF 只用这一条。</li><li>高斯 \\(\\leftrightarrow\\) 高斯：胶模糊、部分照明的光滑源，计算上自闭。</li><li>\\(\\delta(\\mathbf{x})\\leftrightarrow 1\\)：点物的谱是平的，光瞳切它就是在量系统自身。</li><li>平移 \\(t(\\mathbf{x}-\\mathbf{a})\\leftrightarrow T(\\mathbf{f})e^{-2\\pi i\\mathbf{f}\\cdot\\mathbf{a}}\\)：OPC 挪边、邻线位移，全是相因子，不是新原理。</li></ul>',15)),(t(),n(f,null,{default:r(()=>[m(e,{id:"mermaid-65",class:"mermaid",graph:"flowchart%20TD%0A%20%20OBJ%5B%22%E7%89%A9%20t(x)%22%5D%20--%3E%20CONV%5B%22%E7%A9%BA%E5%9F%9F%E5%8D%B7%E7%A7%AF%20*%20h%22%5D%0A%20%20PSF%5B%22%E6%A0%B8%20h%22%5D%20--%3E%20CONV%0A%20%20CONV%20--%3E%20IMG%5B%22%E5%83%8F%22%5D%0A%20%20OBJ%20--%3E%20FT%5B%22%E9%A2%91%E8%B0%B1%20T%22%5D%0A%20%20PSF%20--%3E%20H%5B%22%E4%BC%A0%E9%80%92%20H%22%5D%0A%20%20FT%20--%3E%20MUL%5B%22%E9%A2%91%E5%9F%9F%20T%C2%B7H%22%5D%0A%20%20H%20--%3E%20MUL%0A%20%20MUL%20--%3E%20IMG%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<h3 id="强度不是第二套变换" tabindex="-1">强度不是第二套变换 <a class="header-anchor" href="#强度不是第二套变换" aria-label="Permalink to &quot;强度不是第二套变换&quot;">​</a></h3><p>完全相干：先对场做卷积，再取 \\(|U|^2\\)。交叉项在频域就是一对频率，这正是 Hopkins 双线性的来源，本课不重写 TCC 积分。完全非相干：强度直接与 \\(|h|^2\\) 卷积。产线落在中间，骨架仍是「每一相干切片用一对，再对源积分」。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>锐边 \\(t\\) 的谱拖尾；乘有限 \\(P\\) 再变回空域，等效于与衍射核卷积，边变成斜坡——阿贝课已经用这句话解释糊边。本课补的机制是：<strong>这句话是定理，不是比喻</strong>。后课写采样间隔、写 Airy 半径、写相干截止，都是在给 \\(H\\) 的支撑和 \\(h\\) 的宽度命名，不必再发明「成像公式」。</p><p>周期线栅的 \\(T\\) 是梳状线；卷积定理变成「只让进瞳的那几根齿重新干涉」。斜照明是 \\(T\\) 在频率轴上平移，对仍是同一对，只是窗相对齿移动。RET 改照明，改的是哪些齿落在 \\(H\\) 的支撑里。</p><h3 id="后课默认的接口" tabindex="-1">后课默认的接口 <a class="header-anchor" href="#后课默认的接口" aria-label="Permalink to &quot;后课默认的接口&quot;">​</a></h3><p>说到空中像的线性切片，默认先写卷积或先写 \\(T\\cdot H\\)，再声明相干还是强度。TCC 是部分相干下对这对骨架的组装，不是替代。产线 CD 公式引用<a href="/litho/rayleigh-litho">瑞利判据</a>，光学核引用本课。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课是标量、等晕、傅里叶光学接口。掩模厚度、矢量边界、胶内沉积都不在这对里。也不要把「会写 FFT」当成已经会成像：离散网格、截止与混叠是下一课。禁止发明未发表的变换对；Goodman 第 2 章的表已经够后课引用。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>成像骨架：空域卷积 \\(\\leftrightarrow\\) 频域相乘；光瞳是 \\(H\\) 的一种。</li><li>基本对：rect–sinc、circ–jinc、高斯、δ、平移相位。</li><li>相干先卷积场再取模方；非相干卷积强度；部分相干按源切片用同一对。</li><li>不重推 \\(k_1\\lambda/\\mathrm{NA}\\)；阿贝 / Hopkins / MTF 都建立在这对上。</li><li>下一课：把连续对落到采样网格。</li><li>出处：Goodman, <em>Introduction to Fourier Optics</em>；波动接口见 Born &amp; Wolf。</li></ul>',11))])}const E=o(d,[["render",p]]);export{x as __pageData,E as default};
